  'Configurar más tarde': 'Später konfigurieren',
  'Configurar IA más tarde': 'KI später konfigurieren',
  'Podrás explorar este vault sin IA. Las funciones que analizan, generan contenido o usan búsqueda semántica no estarán disponibles hasta que configures los modelos en Ajustes → Modelos IA.':
    'Sie können diesen Arbeitsbereich ohne KI erkunden. Funktionen zum Analysieren, Erzeugen von Inhalten oder für die semantische Suche bleiben nicht verfügbar, bis Sie die Modelle unter Einstellungen → KI-Modelle konfigurieren.',
  'Explorar sin IA': 'Ohne KI erkunden',
  'Al crear la bóveda, el asistente te llevará a elegir su modelo de IA y su modelo de embeddings, con los modelos de tus proveedores ya cargados.':
    'Nach dem Erstellen des Arbeitsbereichs führt Sie der Assistent zur Auswahl seines KI-Modells und seines Embeddings-Modells, wobei die Modelle Ihrer Anbieter bereits geladen sind.',
  'En el siguiente paso elegirás el modelo de IA y el de embeddings. Nodus detecta tus claves y carga los modelos disponibles por ti.':
    'Im nächsten Schritt wählen Sie das KI-Modell und das Embeddings-Modell aus. Nodus erkennt Ihre Schlüssel und lädt die verfügbaren Modelle für Sie.',
  'Elige un modelo de IA y uno de embeddings para continuar.': 'Wählen Sie ein KI-Modell und ein Embeddings-Modell aus, um fortzufahren.',
  'Hemos detectado tus claves ({list}) y cargado sus modelos automáticamente. Las claves se comparten entre todas tus bóvedas.':
    'Wir haben Ihre Schlüssel ({list}) erkannt und ihre Modelle automatisch geladen. Die Schlüssel werden von allen Ihren Arbeitsbereichen gemeinsam genutzt.',
  'Analiza, escribe y responde.': 'Analysiert, schreibt und antwortet.',
  'Indexa el vault para buscar por significado.': 'Indiziert den Arbeitsbereich für die semantische Suche.',
  'Ningún proveedor respondió todavía.': 'Noch kein Anbieter hat geantwortet.',
  'Sin respuesta de {list}. Puedes continuar con el resto y revisarlo luego en Ajustes → Proveedores.':
    'Keine Antwort von {list}. Sie können mit den übrigen fortfahren und es später unter Einstellungen → Anbieter überprüfen.',
  'Añadir la clave de otro proveedor': 'Schlüssel eines weiteren Anbieters hinzufügen',
  'Guardar y buscar modelos': 'Speichern und Modelle suchen',
  'Buscando modelos…': 'Modelle werden gesucht…',
  'Los modelos marcados como locales se ejecutan en este equipo y no tienen coste por token. Podrás cambiar ambos modelos y añadir favoritos en Ajustes.':
    'Als lokal markierte Modelle laufen auf diesem Computer und verursachen keine Kosten pro Token. Sie können beide Modelle ändern und Favoriten in den Einstellungen hinzufügen.',
  'ya descargado': 'bereits heruntergeladen',
