  'Busca en tu biblioteca personal o en una biblioteca de grupo, elige un elemento y uno de sus adjuntos.':
    'Durchsuchen Sie Ihre persönliche Bibliothek oder eine Gruppenbibliothek und wählen Sie ein Element sowie einen seiner Anhänge aus.',
