  'Este elemento no tiene adjuntos. Puedes enlazar el elemento, pero no importarlo como archivo.':
    'Dieses Element hat keine Anhänge. Sie können das Element verknüpfen, aber nicht als Datei importieren.',
  'Importar el archivo a Nodus': 'Datei in Nodus importieren',
  'Copia el adjunto dentro del vault para leerlo, anotarlo e indexarlo sin depender de Zotero.':
    'Kopiert den Anhang in den Arbeitsbereich, damit er ohne Abhängigkeit von Zotero gelesen, annotiert und indiziert werden kann.',
  'Enlazar con Zotero': 'Mit Zotero verknüpfen',
  'Guarda la referencia en Nodus y abre el elemento o adjunto desde la aplicación Zotero.':
    'Speichert die Referenz in Nodus und öffnet das Element oder den Anhang in der Zotero-App.',
  'Importar a Nodus': 'In Nodus importieren',
  'Crear enlace': 'Verknüpfung erstellen',
  'Importar de Zotero': 'Aus Zotero importieren',
  'Desde el dispositivo': 'Vom Gerät',
  'Enlace de Zotero': 'Zotero-Verknüpfung',
  'Se abre en Zotero': 'Wird in Zotero geöffnet',
  'Abrir origen en Zotero': 'Quelle in Zotero öffnen',
  'Solo puede haber un modo de configuración activo. Cambiar de modo modifica qué selección de modelos utiliza Nodus, no solo la vista de este formulario.':
    'Es kann jeweils nur ein Konfigurationsmodus aktiv sein. Ein Moduswechsel ändert, welche Modellauswahl Nodus verwendet, nicht nur die Ansicht dieses Formulars.',
  'Selección de modelos': 'Modellauswahl',
  'Configuración básica': 'Basiskonfiguration',
  'Configuración avanzada': 'Erweiterte Konfiguration',
  '¿Cambiar a la configuración básica?': 'Zur Basiskonfiguration wechseln?',
  '¿Cambiar a la configuración avanzada?': 'Zur erweiterten Konfiguration wechseln?',
  'Solo un modo puede estar activo. El modelo general pasará a utilizarse en las tareas de texto y las selecciones avanzadas dejarán de aplicarse.':
    'Es kann nur ein Modus aktiv sein. Das allgemeine Modell wird künftig für Textaufgaben verwendet, und die erweiterten Auswahlen gelten nicht mehr.',
  'Después del cambio, revisa y completa «Modelo general de texto» antes de utilizar las funciones de IA. Una configuración incompleta puede hacer que esas funciones fallen.':
    'Überprüfen und vervollständigen Sie nach dem Wechsel „Allgemeines Textmodell“, bevor Sie die KI-Funktionen nutzen. Eine unvollständige Konfiguration kann dazu führen, dass diese Funktionen fehlschlagen.',
  'Solo un modo puede estar activo. Cada tarea pasará a utilizar el modelo seleccionado en su propio campo en lugar de depender únicamente del modelo general.':
    'Es kann nur ein Modus aktiv sein. Jede Aufgabe verwendet künftig das in ihrem eigenen Feld ausgewählte Modell, statt sich allein auf das allgemeine Modell zu verlassen.',
  'Después del cambio, revisa y completa los modelos de «Ajustes avanzados comunes» y del vault actual. Una tarea sin un modelo válido puede fallar.':
    'Überprüfen und vervollständigen Sie nach dem Wechsel die Modelle unter „Gemeinsame erweiterte Einstellungen“ und für den aktuellen Arbeitsbereich. Eine Aufgabe ohne gültiges Modell kann fehlschlagen.',
  'Cambiar a configuración básica': 'Zur Basiskonfiguration wechseln',
  'Cambiar a configuración avanzada': 'Zur erweiterten Konfiguration wechseln',
  'Acerca de Nodus Research': 'Über Nodus Research',
  'Nodus es un proyecto independiente de código abierto, desarrollado y mantenido principalmente por una sola persona. No es un servicio comercial ni un producto de pago: la aplicación seguirá siendo gratuita y su código permanecerá abierto.':
    'Nodus ist ein unabhängiges Open-Source-Projekt, das hauptsächlich von einer einzelnen Person entwickelt und gepflegt wird. Es ist kein kommerzieller Dienst und kein kostenpflichtiges Produkt: Die Anwendung bleibt kostenlos, und ihr Quellcode bleibt offen.',
  'Si Nodus te ayuda a estudiar, investigar o escribir y quieres contribuir voluntariamente a su desarrollo, puedes apoyar el proyecto mediante PayPal o Ko-fi. La donación es completamente opcional: no desbloquea funciones ni cambia el acceso a la aplicación.':
    'Wenn Nodus Ihnen beim Lernen, Forschen oder Schreiben hilft und Sie freiwillig zur weiteren Entwicklung beitragen möchten, können Sie das Projekt über PayPal oder Ko-fi unterstützen. Die Spende ist völlig optional: Sie schaltet keine Funktionen frei und ändert nichts am Zugang zur Anwendung.',
  'Apoyar con PayPal': 'Mit PayPal unterstützen',
  'Apoyar con Ko-fi': 'Mit Ko-fi unterstützen',
  'Apoyar': 'Unterstützen',
  'Comienza': 'Beginnt',
  'Finaliza': 'Endet',
  'Aviso': 'Hinweis',
  'Apoya el proyecto': 'Unterstützen Sie das Projekt',
  'Nodus acaba de mejorar': 'Nodus wurde gerade verbessert',
  "Consulta las nuevas funciones y mejoras de esta versión.": "Hier findest du die neuen Funktionen und Verbesserungen dieser Version.",
  'Nueva versión': 'Neue Version',
  '¡Tenemos novedades!': 'Wir haben Neuigkeiten!',
  'Lo más destacado': 'Höhepunkte',
  'Idiomas': 'Sprachen',
  'APOYO OPCIONAL': 'OPTIONALE UNTERSTÜTZUNG',
  'Explorar las novedades': 'Neuigkeiten entdecken',
  'El enlace se abrirá en tu navegador. Nodus no procesa pagos ni recibe información de pago.':
    'Der Link öffnet sich in Ihrem Browser. Nodus verarbeitet keine Zahlungen und erhält keine Zahlungsinformationen.',
  'COMUNIDAD': 'COMMUNITY',
  'Sigue a Nodus': 'Nodus folgen',
  'Cada versión, los tutoriales nuevos y las dudas de otras personas se comentan en los perfiles públicos del proyecto.': 'Jede Version, die neuen Tutorials und die Fragen anderer werden in den öffentlichen Profilen des Projekts besprochen.',
  'El enlace se abrirá en tu navegador. Seguir el proyecto es opcional y la aplicación no envía nada a estas redes.': 'Der Link öffnet sich in Ihrem Browser. Dem Projekt zu folgen ist freiwillig und die Anwendung sendet nichts an diese Netzwerke.',
  'Mascota Nodi': 'Maskottchen Nodi',
  'Nodi es el nodo que acompaña la app, flotando abajo a la derecha. Haz clic en Nodi para abrir el chat, tus notificaciones y la ayuda.':
    'Nodi ist der Knoten, der die App begleitet und unten rechts schwebt. Klicken Sie auf Nodi, um den Chat, Ihre Benachrichtigungen und die Hilfe zu öffnen.',
  'Mostrar a Nodi': 'Nodi anzeigen',
  'Aspecto de Nodi': 'Aussehen von Nodi',
  'Elige el Nodi que te acompaña. El cambio se aplica en toda la app.': 'Wählen Sie den Nodi, der Sie begleitet. Die Änderung gilt in der gesamten App.',
  'Nodi clásico': 'Klassischer Nodi',
  'El personaje de siempre, con sus gestos y sus trajes según la bóveda.': 'Die vertraute Figur, mit ihren Gesten und ihren Kostümen je nach Arbeitsbereich.',
