  'URL del servidor': 'Server-URL',
  'Bearer token': 'Bearer-Token',
  'Activa el servidor para generar un token.': 'Aktivieren Sie den Server, um einen Token zu generieren.',
  'Si tu versión permite conectores MCP remotos, añade la URL y la cabecera de autorización. Como alternativa compatible, usa este puente stdio y reinicia Claude Desktop:':
    'Wenn Ihre Version entfernte MCP-Connectoren unterstützt, fügen Sie die URL und den Autorisierungsheader hinzu. Als kompatible Alternative verwenden Sie diese stdio-Brücke und starten Sie Claude Desktop neu:',
  'Añade un servidor MCP con esta URL y la cabecera de autorización en Connectors/Developer mode. ChatGPT web no puede acceder a 127.0.0.1: necesitarías un túnel HTTPS externo, que no forma parte de Nodus. Si expones el servidor, protege el token.':
    'Fügen Sie im Connectors/Developer-Modus einen MCP-Server mit dieser URL und dem Autorisierungsheader hinzu. ChatGPT im Web kann nicht auf 127.0.0.1 zugreifen: Sie bräuchten einen externen HTTPS-Tunnel, der nicht Teil von Nodus ist. Wenn Sie den Server exponieren, schützen Sie den Token.',
