  'Fusionar todos los duplicados': 'Alle Duplikate zusammenführen',
  'Se fusionarán {g} grupo(s), conservando en cada uno la copia marcada y reasignando sus ideas, evidencia y etiquetas. Las {n} copias sobrantes se eliminarán de la biblioteca de Nodus (Zotero no se modifica). ¿Continuar?':
    'Es werden {g} Gruppe(n) zusammengeführt, wobei in jeder die markierte Kopie beibehalten und ihre Ideen, Belege und Tags neu zugewiesen werden. Die {n} überzähligen Kopien werden aus der Nodus-Bibliothek entfernt (Zotero wird nicht verändert). Fortfahren?',
  'Duplicados': 'Duplikate',
  'Buscar y fusionar ideas duplicadas para limpiar el grafo y el listado':
    'Doppelte Ideen suchen und zusammenführen, um den Graphen und die Liste zu bereinigen',
  'Ideas duplicadas': 'Doppelte Ideen',
  'Buscando ideas duplicadas…': 'Doppelte Ideen werden gesucht…',
  'No se han encontrado ideas duplicadas.': 'Es wurden keine doppelten Ideen gefunden.',
  '{g} grupo(s) · {n} idea(s) duplicadas a fusionar': '{g} Gruppe(n) · {n} doppelte Idee(n) zum Zusammenführen',
  'Solo se agrupan ideas con la misma etiqueta y el mismo tipo. La evidencia se conserva íntegra al fusionar.':
    'Es werden nur Ideen mit demselben Label und demselben Typ gruppiert. Die Belege bleiben beim Zusammenführen vollständig erhalten.',
  'Misma etiqueta': 'Gleiches Label',
  'Copia de seguridad creada antes de fusionar:': 'Vor dem Zusammenführen erstellte Sicherung:',
  '{n} evidencia(s)': '{n} Beleg(e)',
  'Fusionar todas las ideas duplicadas': 'Alle doppelten Ideen zusammenführen',
  'Se hará primero una copia de seguridad completa de la base de datos. Después se fusionarán {g} grupo(s), conservando en cada uno la idea marcada y reasignándole toda la evidencia, ocurrencias, temas y conexiones del grafo de las {n} copias sobrantes, que se eliminarán. La evidencia no se pierde. ¿Continuar?':
    'Zuerst wird eine vollständige Sicherung der Datenbank erstellt. Anschließend werden {g} Gruppe(n) zusammengeführt, wobei in jeder die markierte Idee beibehalten wird und ihr alle Belege, Vorkommen, Themen und Graphverbindungen der {n} überzähligen Kopien zugewiesen werden, die anschließend entfernt werden. Es gehen keine Belege verloren. Fortfahren?',
  'Seleccionar los {n} resultados filtrados': 'Die {n} gefilterten Ergebnisse auswählen',
