  'Esta obra aún no tiene ideas extraídas.': 'Für dieses Werk wurden noch keine Ideen extrahiert.',
  'Ejecuta un análisis profundo de la obra para verla en el grafo.': 'Führen Sie eine tiefe Analyse des Werks durch, um es im Graphen zu sehen.',
  'Ideas de la obra': 'Ideen des Werks',
