  'Preparar búsqueda semántica': 'Semantische Suche vorbereiten',
  'Indexar texto citable': 'Zitierfähigen Text indexieren',
  'Genera los embeddings que faltan para poder encontrar ideas por significado. No regenera los existentes.': 'Erzeugt die fehlenden Embeddings, damit Ideen nach Bedeutung gefunden werden. Vorhandene werden nicht neu erzeugt.',
  'Preparar las que falten': 'Fehlende vorbereiten',
  'Indexa los fragmentos de texto completo que falten o estén obsoletos, en toda la biblioteca. No requiere análisis de ideas y los ya actuales se omiten.': 'Indexiert die fehlenden oder veralteten Volltextfragmente in der gesamten Bibliothek. Erfordert keine Ideenanalyse und überspringt bereits aktuelle.',
  'Indexar lo que falte': 'Fehlendes indexieren',
  'Filtros avanzados': 'Erweiterte Filter',
  'Combina condiciones sueltas de la tubería de análisis. Los presets de arriba cubren los casos habituales.': 'Kombiniere einzelne Bedingungen der Analysekette. Die Voreinstellungen oben decken die üblichen Fälle ab.',
  'Ver el detalle paso a paso': 'Detail Schritt für Schritt ansehen',
  'Necesita el texto completo de la obra.': 'Benötigt den Volltext des Werks.',
  'El análisis solo pudo usar el abstract.': 'Die Analyse konnte nur das Abstract verwenden.',
  'Disponible en la obra.': 'Beim Werk verfügbar.',
  '{n} fragmentos indexados': '{n} indexierte Fragmente',
  'Enviando…': 'Wird gesendet…',
  'Faltan {n} paso(s). Se encolarán y verás el progreso en la cola.': '{n} Schritt(e) fehlen. Sie werden eingereiht und du siehst den Fortschritt in der Warteschlange.',
  'No queda nada pendiente en esta obra.': 'Bei diesem Werk steht nichts mehr aus.',
  'Reintentar lo que falta': 'Fehlendes erneut versuchen',
  'Encola solo los pasos incompletos, pendientes o fallidos de cada obra seleccionada. No vuelve a analizar lo que ya está hecho.': 'Reiht nur die unvollständigen, ausstehenden oder fehlgeschlagenen Schritte jedes ausgewählten Werks ein. Bereits Erledigtes wird nicht erneut analysiert.',
  'No queda nada pendiente en la selección.': 'In der Auswahl steht nichts mehr aus.',
  'Pendientes en cola para {n} obra(s). Verás el progreso en la cola.': 'Ausstehende Schritte für {n} Werk(e) eingereiht. Du siehst den Fortschritt in der Warteschlange.',
  'Eliminar las {n} obras seleccionadas': 'Die {n} ausgewählten Werke löschen',
  'Se eliminarán del vault actual las {n} obra(s) seleccionada(s), junto con sus ideas extraídas, sus pasajes, sus embeddings y el resto de datos derivados. Las ideas y demás datos que compartan con otras obras se conservan. Esta acción no se puede deshacer.': 'Die {n} ausgewählte(n) Werk(e) werden aus dem aktuellen Arbeitsbereich gelöscht, zusammen mit ihren extrahierten Ideen, Passagen, Embeddings und den übrigen abgeleiteten Daten. Ideen und andere Daten, die sie mit anderen Werken teilen, bleiben erhalten. Das lässt sich nicht rückgängig machen.',
  'Elimina estas obras del vault actual con sus ideas, pasajes, embeddings y demás datos derivados. Lo que otras obras comparten no se toca.': 'Löscht diese Werke aus dem aktuellen Arbeitsbereich samt Ideen, Passagen, Embeddings und weiteren abgeleiteten Daten. Was andere Werke teilen, bleibt unberührt.',
  'No se pueden eliminar obras que se están analizando ahora mismo ({n}). Espera a que terminen o detén la cola.': 'Werke, die gerade analysiert werden, lassen sich nicht löschen ({n}). Warte, bis sie fertig sind, oder stoppe die Warteschlange.',
  'Se eliminaron {n} obra(s) del vault.': '{n} Werk(e) aus dem Arbeitsbereich gelöscht.',
  'No se pudieron eliminar las obras seleccionadas.': 'Die ausgewählten Werke konnten nicht gelöscht werden.',
  'No aplica': 'Nicht zutreffend',
  'Solo abstract': 'Nur Abstract',
  'Nodus no encontró texto que leer. Añade el PDF o EPUB en Zotero y vuelve a analizar.': 'Nodus hat keinen lesbaren Text gefunden. Füge das PDF oder EPUB in Zotero hinzu und analysiere erneut.',
  'Zotero no está disponible. Ábrelo y vuelve a analizar.': 'Zotero ist nicht verfügbar. Öffne es und analysiere erneut.',
  'El análisis solo pudo usar el abstract, así que esta obra no tendrá texto citable. Añade el PDF o EPUB en Zotero y vuelve a analizar.': 'Die Analyse konnte nur das Abstract verwenden, daher wird dieses Werk keinen zitierfähigen Text haben. Füge das PDF oder EPUB in Zotero hinzu und analysiere erneut.',
  'Ver las {n} ideas de esta obra': 'Die {n} Ideen dieses Werks ansehen',
  'Analizar: temas, ideas, resumen, indexado y relaciones': 'Analysieren: Themen, Ideen, Zusammenfassung, Indexierung und Beziehungen',
  'Más acciones': 'Weitere Aktionen',
  'Analizar solo temas': 'Nur Themen analysieren',
