  'Con fallos': 'Mit Fehlern',
  'Incompleto': 'Unvollständig',
  'Búsqueda semántica': 'Semantische Suche',
  'Texto citable': 'Zitierfähiger Text',
  'Pulsa «Analizar» en la fila de una obra, o selecciona varias y analízalas juntas. Nodus lee el texto, extrae temas padre, ideas con evidencia y relaciones, y las añade al grafo. La columna Estado te dice en qué punto va cada obra.': 'Klicke in der Zeile eines Werks auf «Analysieren» oder wähle mehrere aus und analysiere sie gemeinsam. Nodus liest den Text, extrahiert Oberthemen, Ideen mit Belegen und Beziehungen und fügt sie dem Graphen hinzu. Die Spalte Status zeigt, wie weit jedes Werk ist.',
  'Procesar todo: temas, ideas, resumen, indexado y relaciones': 'Alles verarbeiten: Themen, Ideen, Zusammenfassung, Indexierung und Beziehungen',
