    'Analysieren Sie diese Lektüre innerhalb des Korpus: extrahierte Ideen, Themen, Lücken, Widersprüche und verwandte nächste Lektüren.',
  'Reasignar temas vuelve a ejecutar el análisis ligero (título + abstract) sobre TODA la biblioteca para reconstruir los temas padre y agrupar las ideas existentes bajo ellos. Consume tokens del modelo seleccionado. ¿Continuar?':
    'Themen neu zuweisen führt die leichte Analyse (Titel + Abstract) erneut über die GESAMTE Bibliothek aus, um die übergeordneten Themen neu aufzubauen und die bestehenden Ideen darunter zu gruppieren. Verbraucht Tokens des ausgewählten Modells. Fortfahren?',
