    'Gespeicherter Bericht geöffnet. Sie können ihn exportieren oder seine Idee wiederverwenden, um ihn neu zu erzeugen.',
  'Idea reutilizada: ajusta los parámetros y genera un informe actualizado.':
    'Idee wiederverwendet: Passen Sie die Parameter an und erzeugen Sie einen aktualisierten Bericht.',
  '¿Eliminar este informe guardado? Esta acción no se puede deshacer.':
    'Diesen gespeicherten Bericht löschen? Diese Aktion kann nicht rückgängig gemacht werden.',
  'Informe eliminado.': 'Bericht gelöscht.',
  '1. Plantea la idea': '1. Idee festlegen',
  'Escribe la pregunta o idea de investigación que quieres desarrollar. El informe la convierte en un texto de varias páginas, no en una respuesta corta.':
    'Schreiben Sie die Forschungsfrage oder -idee, die Sie entwickeln möchten. Der Bericht macht daraus einen mehrseitigen Text, keine kurze Antwort.',
  '2. Ajusta el alcance': '2. Umfang festlegen',
  'Elige la extensión objetivo y el número máximo de secciones. Menos secciones producen un texto más profundo; más secciones, uno más panorámico.':
    'Wählen Sie den Ziel-Umfang und die maximale Anzahl an Abschnitten. Weniger Abschnitte ergeben einen tiefergehenden Text, mehr Abschnitte einen umfassenderen.',
  '3. Cobertura del corpus': '3. Abdeckung des Corpus',
  'Nodus recorre todo el corpus indexado, planifica las secciones y redacta guiado por la cobertura, citando cada obra sin que tengas que seleccionarla.':
    'Nodus durchsucht den gesamten indizierten Corpus, plant die Abschnitte und schreibt, geleitet von der Abdeckung, wobei jedes Werk zitiert wird, ohne dass Sie es auswählen müssen.',
  '4. Revisa y exporta': '4. Überprüfen und exportieren',
  'Abre las citas para comprobar cada fuente, guarda el informe para retomarlo y expórtalo a Markdown o PDF cuando esté listo.':
    'Öffnen Sie die Zitate, um jede Quelle zu prüfen, speichern Sie den Bericht, um ihn später fortzusetzen, und exportieren Sie ihn als Markdown oder PDF, sobald er fertig ist.',
  'Informe académico de varias páginas, guiado por cobertura y con todas las fuentes citadas.':
    'Mehrseitiger wissenschaftlicher Bericht, abdeckungsgeleitet und mit allen zitierten Quellen.',
