  'Quiero estudiar este autor como parte de mi corpus. Prioriza tesis, ideas, obras que debo abrir en Zotero, pasajes y contradicciones:':
    'Ich möchte diesen Autor als Teil meines Korpus lernen. Priorisieren Sie These, Ideen, Werke, die ich in Zotero öffnen sollte, Passagen und Widersprüche:',
  'Modo Estudio: domina autores e ideas': 'Lernmodus: Autoren und Ideen meistern',
  'Cuando el objetivo sea aprender el corpus, entra en Estudio: Nodus prioriza autores, recomienda obras concretas para abrir en Zotero, propone sesiones tutor con pasajes y te permite marcar qué está entendido, qué queda en repaso y qué exige lectura completa.':
    'Wenn das Ziel darin besteht, den Korpus zu lernen, öffnen Sie Lernen: Nodus priorisiert Autoren, empfiehlt konkrete Werke zum Öffnen in Zotero, schlägt Tutor-Sitzungen mit Passagen vor und ermöglicht es Ihnen, zu markieren, was verstanden ist, was noch wiederholt werden muss und was eine vollständige Lektüre erfordert.',
