  'Semantic Scholar': 'Semantic Scholar',
  'El grafo no se pudo renderizar': 'Der Graph konnte nicht dargestellt werden',
  'Carga un corpus de demostración de seis obras sobre la ciencia del aprendizaje. Podrás recorrer el grafo, ideas, debates, huecos y notas sin conectar Zotero ni configurar una clave de IA.':
    'Laden Sie ein Demo-Korpus mit sechs Werken über die Wissenschaft des Lernens. Sie können den Graphen, Ideen, Debatten, Lücken und Notizen erkunden, ohne Zotero zu verbinden oder einen KI-Schlüssel einzurichten.',
  'Cargar demo': 'Demo laden',
  'Explora con datos de ejemplo': 'Mit Beispieldaten erkunden',
  'Prueba sin configurar nada': 'Ausprobieren ohne Konfiguration',
  'Crea resúmenes de orientación independientes a partir de ideas, evidencia, temas y abstract. No son evidencia citable.':
    'Erstellt eigenständige Orientierungszusammenfassungen aus Ideen, Belegen, Themen und Abstract. Sie sind keine zitierfähigen Belege.',
  'El análisis profundo solo usó el abstract, no el texto completo (el PDF/EPUB no estaba disponible al analizar). Reanaliza cuando esté en Zotero.':
    'Die Tiefenanalyse hat nur das Abstract verwendet, nicht den Volltext (das PDF/EPUB war bei der Analyse nicht verfügbar). Analysieren Sie erneut, sobald es in Zotero verfügbar ist.',
  'El texto o el modelo de embeddings cambió.': 'Der Text oder das Embedding-Modell hat sich geändert.',
  'Las ideas pertenecen a la versión anterior del texto. Vuelve a analizarlas para usar el texto actual.': 'Die Ideen gehören zur vorherigen Textversion. Analysieren Sie sie erneut, um den aktuellen Text zu verwenden.',
  'El texto cambió; vuelve a indexar sus fragmentos.': 'Der Text hat sich geändert; indexieren Sie seine Passagen erneut.',
  'Los fragmentos se indexaron con otro modelo de embeddings.': 'Die Passagen wurden mit einem anderen Embedding-Modell indexiert.',
  'El texto y el modelo de embeddings cambiaron.': 'Sowohl der Text als auch das Embedding-Modell haben sich geändert.',
  'Algunos fragmentos no tienen un embedding válido.': 'Einige Passagen haben kein gültiges Embedding.',
  'Generar resúmenes faltantes': 'Fehlende Zusammenfassungen erstellen',
  'Indexa fragmentos de texto completo en las obras que faltan o están obsoletas. No requiere análisis de ideas; el texto se mantiene como evidencia citable.':
    'Indiziert Volltextausschnitte in Werken, die fehlen oder veraltet sind. Erfordert keine Ideenanalyse; der Text bleibt als zitierfähiger Beleg erhalten.',
  'Indexar pasajes': 'Passagen indizieren',
  'Indexar pasajes de esta obra': 'Passagen dieses Werks indizieren',
  'Indexar todo': 'Alles indizieren',
  'No hay obras «solo abstract» para reanalizar.': 'Es gibt keine Werke „nur Abstract“, die erneut analysiert werden könnten.',
  'obsoleto': 'veraltet',
  'Pasajes (texto completo)': 'Passagen (Volltext)',
  'Procesar faltantes': 'Fehlende verarbeiten',
  'Procesar pasajes faltantes': 'Fehlende Passagen verarbeiten',
  'Reanálisis en cola para {n} obra(s) «solo abstract». Verás el progreso en la cola.':
    'Erneute Analyse für {n} Werk(e) „nur Abstract“ eingereiht. Den Fortschritt sehen Sie in der Warteschlange.',
  'Reanaliza las obras que solo se analizaron con el abstract (el PDF/EPUB no estaba disponible al analizarlas). Las que ya tengan el texto disponible en Zotero recuperarán el análisis completo; el resto se omiten sin coste. ¿Continuar?':
    'Analysiert die Werke erneut, die nur mit dem Abstract analysiert wurden (das PDF/EPUB war bei der Analyse nicht verfügbar). Werke, deren Text inzwischen in Zotero verfügbar ist, erhalten die vollständige Analyse; die übrigen werden ohne Kosten übersprungen. Fortfahren?',
  'Reanalizar': 'Erneut analysieren',
  'Reanalizar «solo abstract»': '„Nur Abstract“ erneut analysieren',
  'Recorre toda la biblioteca y actualiza solo los índices que hayan cambiado. Los ya actuales se omiten.':
    'Durchsucht die gesamte Bibliothek und aktualisiert nur die geänderten Indizes. Bereits aktuelle werden übersprungen.',
  'resumen': 'Zusammenfassung',
  'solo abstract': 'nur Abstract',
  'Vuelve a analizar las obras cuyo análisis profundo solo usó el abstract porque el PDF/EPUB no estaba disponible. Las que ya tengan el texto recuperan el análisis completo; el resto se omiten sin coste.':
    'Analysiert Werke erneut, deren Tiefenanalyse nur das Abstract verwendet hat, weil das PDF/EPUB nicht verfügbar war. Werke mit inzwischen verfügbarem Text erhalten die vollständige Analyse; die übrigen werden ohne Kosten übersprungen.',
  'Añade citas textuales con su página o rango de páginas.': 'Fügt wörtliche Zitate mit Seite oder Seitenbereich hinzu.',
