  'Reinicializar el grafo': 'Graph zurücksetzen',
  'Reinicializar el grafo borrará TODAS las ideas, temas, conexiones, autores y huecos, y dejará cada obra sin analizar. Tu biblioteca de Zotero y tus ajustes se conservan. Esta acción no se puede deshacer.':
    'Das Zurücksetzen des Graphen löscht ALLE Ideen, Themen, Verbindungen, Autoren und Lücken und lässt jedes Werk unanalysiert zurück. Ihre Zotero-Bibliothek und Ihre Einstellungen bleiben erhalten. Diese Aktion kann nicht rückgängig gemacht werden.',
