  'Algo ha fallado en esta sección': 'In diesem Bereich ist ein Fehler aufgetreten',
  'Se produjo un error inesperado al mostrar esta vista. El resto de la app sigue funcionando: reinténtalo o cambia de sección.':
    'Beim Anzeigen dieser Ansicht ist ein unerwarteter Fehler aufgetreten. Der Rest der App funktioniert weiterhin: Versuchen Sie es erneut oder wechseln Sie den Bereich.',
  'Recargar Nodus': 'Nodus neu laden',
  'Inmersión': 'Immersion',
  'Domina un tema de tu corpus en una tarde.': 'Beherrschen Sie ein Thema Ihres Korpus an einem Nachmittag.',
  'Una ruta completamente guiada: panorama, estaciones con citas literales del texto completo, contrastes entre autores, fronteras del corpus y examen final. Todo queda grabado para retomarlo cuando quieras.':
    'Eine vollständig geführte Route: Überblick, Stationen mit wörtlichen Zitaten aus dem Volltext, Kontraste zwischen Autoren, Grenzen des Korpus und Abschlussprüfung. Alles wird aufgezeichnet, damit Sie es jederzeit fortsetzen können.',
  '¿De qué quieres hacerte experto? P. ej.: uso franquista de las fiestas y tradiciones':
    'Worin möchten Sie Experte werden? Z. B.: franquistische Nutzung von Festen und Traditionen',
