  'p. {p}': 'S. {p}',
  'Quién dice qué, frente a frente': 'Wer sagt was, im direkten Vergleich',
  'La matriz que distingue a un experto: cada autor frente a cada sub-pregunta. Las celdas vacías también informan — ese autor no se pronuncia ahí.':
    'Die Matrix, die einen Experten auszeichnet: jeder Autor im Vergleich zu jeder Unterfrage. Auch leere Zellen sagen etwas aus — dieser Autor äußert sich dort nicht.',
  'No hay suficientes autores con posiciones diferenciadas en este tema.': 'Es gibt nicht genügend Autoren mit unterschiedlichen Positionen zu diesem Thema.',
  'Sub-pregunta': 'Unterfrage',
  'Lo que tu corpus no sabe (todavía)': 'Was Ihr Korpus (noch) nicht weiß',
  'Conocer los límites es parte de la maestría: aquí terminan tus fuentes y empieza el trabajo futuro.':
    'Die Grenzen zu kennen ist Teil der Meisterschaft: Hier enden Ihre Quellen und beginnt zukünftige Arbeit.',
  'No se detectaron huecos relevantes para este tema. Buen síntoma.': 'Für dieses Thema wurden keine relevanten Lücken festgestellt. Ein gutes Zeichen.',
  'Inmersión completada': 'Immersion abgeschlossen',
  'Demuestra que eres experto': 'Zeigen Sie, dass Sie Experte sind',
  'Cubre todas las estaciones. Cada pregunta es opcional: respóndelas para medirte o sáltalas sin más.':
    'Deckt alle Stationen ab. Jede Frage ist optional: Beantworten Sie sie, um sich selbst zu testen, oder überspringen Sie sie einfach.',
  'Sesión sin preguntas: cierra con la explicación final y da la inmersión por completada.':
    'Sitzung ohne Fragen: Schließt mit der abschließenden Erklärung und markiert die Immersion als abgeschlossen.',
