  'Falta la clave del proveedor de IA: configúrala en Ajustes': 'Der Schlüssel des KI-Anbieters fehlt: Richten Sie ihn in den Einstellungen ein',
  'Profundiza: informe Deep Research del tema': 'Vertiefen: Deep-Research-Bericht zum Thema',
  'Ahora que dominas el tema, genera el informe académico de varias páginas con todas las fuentes citadas. Se guarda en Deep Research y podrás exportarlo o citarlo en tu escritura.':
    'Jetzt, da Sie das Thema beherrschen, erstellen Sie den mehrseitigen wissenschaftlichen Bericht mit allen zitierten Quellen. Er wird in Deep Research gespeichert, sodass Sie ihn exportieren oder in Ihrem Text zitieren können.',
  'Puedes cambiar de sección: el informe seguirá generándose y mostrará el progreso al volver.':
    'Sie können den Bereich wechseln: Der Bericht wird weiter generiert und zeigt den Fortschritt, wenn Sie zurückkehren.',
  'Dossier guardado: «{t}» · {s} secciones · ~{p} páginas. Lo tienes en Deep Research → informes guardados.':
    'Dossier gespeichert: „{t}“ · {s} Abschnitte · ~{p} Seiten. Sie finden es in Deep Research → gespeicherte Berichte.',
  'Generar de nuevo': 'Erneut generieren',
  'Seleccionar modelo': 'Modell auswählen',
  'Usar modelo de síntesis': 'Synthesemodell verwenden',
  'Modelo inicial para las tareas de IA ({n} disponibles)': 'Ausgangsmodell für KI-Aufgaben ({n} verfügbar)',
  'Modelos favoritos para los selectores independientes': 'Favoritenmodelle für unabhängige Auswahlmenüs',
  'Los modelos de análisis se configuran en Ajustes.': 'Die Analysemodelle werden in den Einstellungen konfiguriert.',
  'Modelos de análisis: Ajustes': 'Analysemodelle: Einstellungen',
  'coge las ideas ya extraídas (afirmaciones, hallazgos…) y las vuelve a agrupar bajo estos temas con los modelos configurados en Ajustes, sin volver a leer los documentos ni re-extraer ideas.':
    'nimmt die bereits extrahierten Ideen (Aussagen, Erkenntnisse…) und gruppiert sie mit den in den Einstellungen konfigurierten Modellen erneut unter diesen Themen, ohne die Dokumente erneut zu lesen oder Ideen neu zu extrahieren.',
  'Cada tarea usa su propio modelo. Los escaneos, resúmenes, fusión y embeddings obedecen estos ajustes; Chat, Deep Research, Inmersión y las demás herramientas conservan el modelo elegido dentro de su propia sección.':
    'Jede Aufgabe verwendet ihr eigenes Modell. Scans, Zusammenfassungen, Fusion und Embeddings folgen diesen Einstellungen; Chat, Deep Research, Immersion und die übrigen Werkzeuge behalten das in ihrem eigenen Bereich gewählte Modell.',
  'Modelo de síntesis general (fallback inicial para herramientas con selector propio)':
    'Allgemeines Synthesemodell (anfängliches Fallback für Werkzeuge mit eigener Auswahl)',
  'modelos por tarea': 'Modelle nach Aufgabe',
  'Extracción: {provider}': 'Extraktion: {provider}',
  'Síntesis: {provider}': 'Synthese: {provider}',
  'Configura los modelos de IA': 'Konfigurieren Sie die KI-Modelle',
  'La sincronización puede funcionar, pero Nodus necesita modelos separados de extracción y síntesis para analizar el corpus.':
    'Die Synchronisierung kann funktionieren, aber Nodus benötigt separate Modelle für Extraktion und Synthese, um das Korpus zu analysieren.',
  'Generación de imágenes': 'Bildgenerierung',
  'Configuración independiente para las imágenes decorativas opcionales. OpenAI usa su API oficial de imágenes y reutiliza la clave de OpenAI; Google reutiliza la clave de Gemini.':
    'Unabhängige Konfiguration für die optionalen dekorativen Bilder. OpenAI verwendet seine offizielle Bilder-API und nutzt den OpenAI-Schlüssel weiter; Google nutzt den Gemini-Schlüssel weiter.',
