  'Como los proveedores publican tamaños y métricas diferentes, la ordenación por precio se aplica por separado dentro de cada proveedor. Los modelos sin precio directo quedan al final; no se estiman costes.':
    'Da die Anbieter unterschiedliche Größen und Metriken veröffentlichen, wird die Preissortierung innerhalb jedes Anbieters separat angewendet. Modelle ohne direkten Preis erscheinen am Ende; Kosten werden nicht geschätzt.',
