    '{n} Immersionen und deren gesamten Fortschritt löschen? Diese Aktion kann nicht rückgängig gemacht werden.',
  'Nueva inmersión': 'Neue Immersion',
  'Domina un tema de tu corpus: panorama, estaciones con citas literales, contrastes, fronteras y examen final. Todo queda grabado para retomarlo.':
    'Meistern Sie ein Thema Ihres Korpus: Überblick, Stationen mit wörtlichen Zitaten, Kontraste, Grenzen und Abschlussprüfung — alles wird gespeichert, um später fortzufahren.',
  'Domina un tema de tu corpus: el contenido y el progreso se guardan para retomarlos; tus respuestas se borran al reiniciar.':
    'Meistern Sie ein Thema Ihres Korpus: Inhalt und Fortschritt werden gespeichert, damit Sie fortfahren können; Ihre Antworten werden beim Neustart gelöscht.',
  'Buscar entre tus inmersiones…': 'In Ihren Immersionen suchen…',
  'Cargando inmersiones…': 'Immersionen werden geladen…',
  'Ninguna inmersión coincide con tu búsqueda.': 'Keine Immersion entspricht Ihrer Suche.',
  'Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso y tus respuestas, lista para retomarla.':
    'Noch keine Immersionen. Erstellen Sie die erste; sie bleibt hier mit ihrem Fortschritt und Ihren Antworten, bereit zum Fortfahren.',
  'Aún no hay inmersiones. Crea la primera y quedará aquí, con su progreso, lista para retomarla.':
    'Noch keine Immersionen. Erstellen Sie die erste; sie bleibt hier mit ihrem Fortschritt, bereit zum Fortfahren.',
  'Reiniciar borra las respuestas anteriores y comienza el recorrido desde el principio.':
    'Ein Neustart löscht die bisherigen Antworten und beginnt den Rundgang von vorn.',
  'Elige el tema y el alcance. Antes de generar verás qué sabe tu corpus (sin IA).':
    'Wählen Sie das Thema und den Umfang. Vor dem Erstellen sehen Sie, was Ihr Korpus weiß (ohne KI).',
  'Duración': 'Dauer',
  'Novedades': 'Neuigkeiten',
  'Esto es lo nuevo en esta versión de Nodus.': 'Das ist neu in dieser Version von Nodus.',
  '¡Entendido!': 'Verstanden!',
  'Plegar': 'Einklappen',
  'Desplegar': 'Ausklappen',
  'Elige las colecciones a monitorizar. Despliega cualquier colección para elegir subcolecciones concretas si una es demasiado grande. Se incorporan metadatos; los análisis se lanzan manualmente salvo que actives automatización en Ajustes.':
    'Wählen Sie die zu überwachenden Sammlungen. Klappen Sie eine Sammlung aus, um bei Bedarf einzelne Untersammlungen auszuwählen, falls eine zu groß ist. Metadaten werden importiert; Analysen werden manuell gestartet, sofern Sie die Automatisierung nicht in den Einstellungen aktivieren.',
