  'Vamos a crear tu primera bóveda': 'Richten wir Ihren ersten Vault ein',
  'Ponle un nombre y elige su modo. El modo decide qué secciones verás y cómo trabaja la IA contigo; puedes crear más bóvedas, de otros modos, cuando quieras.': 'Geben Sie ihm einen Namen und wählen Sie seinen Modus. Der Modus entscheidet, welche Bereiche Sie sehen und wie die KI mit Ihnen arbeitet; weitere Vaults in anderen Modi können Sie jederzeit anlegen.',
  'Después el asistente te ayudará a elegir su modelo de IA y su modelo de embeddings. Puedes cambiar el nombre en cualquier momento desde el selector de bóvedas.': 'Anschließend hilft Ihnen der Assistent bei der Wahl des KI- und des Embedding-Modells. Den Namen können Sie jederzeit über die Vault-Auswahl ändern.',
