  '{s} estaciones · {i} ideas · {w} obras · ~{m} minutos': '{s} Stationen · {i} Ideen · {w} Werke · ~{m} Minuten',
  'Elige y prepara una voz en Ajustes → IA → Audio y voz.': 'Wählen und richten Sie eine Stimme in Einstellungen → KI → Audio und Stimme ein.',
  'No hay texto narrable en este contenido.': 'In diesem Inhalt gibt es keinen vorlesbaren Text.',
  'Audio': 'Audio',
  '{n} pistas': '{n} Titel',
  'Reproducir todo': 'Alles abspielen',
  'Eliminar audio': 'Audio löschen',
  'Generar audio': 'Audio generieren',
  'Elige y prepara una voz en Ajustes → IA → Audio y voz para poder narrar.':
    'Wählen und richten Sie eine Stimme in Einstellungen → KI → Audio und Stimme ein, um vorlesen zu können.',
  'Faltan algunos archivos de audio (no se guardan en las copias de seguridad). Pulsa Regenerar para recuperarlos.':
    'Einige Audiodateien fehlen (sie werden nicht in Sicherungen gespeichert). Klicken Sie auf Neu generieren, um sie wiederherzustellen.',
  'Archivo no disponible': 'Datei nicht verfügbar',
  'Pausa': 'Pause',
