  'Tres tablas de investigación con todos los tipos de columna, relaciones, registros, análisis, una conversación y notas de ejemplo. Incluye un tutorial guiado.':
    'Drei Forschungstabellen mit allen Spaltentypen, Relationen, Datensätzen, Analysen, einer Unterhaltung und Beispielnotizen. Enthält ein geführtes Tutorial.',
  'Cargar demo de bases de datos': 'Datenbanken-Demo laden',
  'Cargar datos de ejemplo': 'Beispieldaten laden',
  'Tutorial de bases de datos': 'Datenbanken-Tutorial',
  'La lista de bases de datos, la tabla con columnas tipadas, la edición de celdas y las secciones de análisis y chat.':
    'Die Liste der Datenbanken, die Tabelle mit typisierten Spalten, die Zellbearbeitung sowie die Bereiche Analyse und Chat.',
  'Se mostrará el tutorial de bases de datos.': 'Das Datenbanken-Tutorial wird angezeigt.',
  'Bienvenido al modo bases de datos': 'Willkommen im Datenbanken-Modus',
  'Este es el modo bases de datos de Nodus: un gestor de tablas al estilo Notion, integrado en tu app. Te enseño en un minuto sus piezas con tres bases de datos de ejemplo ya cargadas. Puedes salir cuando quieras y volver a ver el tutorial desde Ajustes.':
    'Dies ist der Datenbanken-Modus von Nodus: ein Tabellenmanager im Notion-Stil, direkt in Ihre App integriert. In einer Minute zeige ich Ihnen seine Bestandteile anhand von drei bereits geladenen Beispieldatenbanken. Sie können jederzeit aussteigen und das Tutorial später über die Einstellungen erneut aufrufen.',
  'Tus bases de datos': 'Ihre Datenbanken',
  'En la barra lateral aparecen todas tus bases de datos. Cada una tiene un identificador único autogenerado. Pulsa una para abrirla, o el botón + para crear una nueva. Aquí abajo están también las secciones de Análisis y Chat.':
    'In der Seitenleiste erscheinen alle Ihre Datenbanken. Jede hat eine automatisch generierte eindeutige ID. Klicken Sie auf eine, um sie zu öffnen, oder auf die Schaltfläche +, um eine neue zu erstellen. Hier unten befinden sich auch die Bereiche Analyse und Chat.',
  'La tabla': 'Die Tabelle',
  'Cada base de datos es una tabla de columnas tipadas: título, texto, número, fecha, hora, selección, selección múltiple y casilla. Arriba verás el número total de entradas y el porcentaje que suponen del total de todas tus bases de datos.':
    'Jede Datenbank ist eine Tabelle mit typisierten Spalten: Titel, Text, Zahl, Datum, Uhrzeit, Auswahl, Mehrfachauswahl und Kontrollkästchen. Oben sehen Sie die Gesamtzahl der Einträge und deren Anteil an allen Ihren Datenbanken.',
  'Edita directamente': 'Direkt bearbeiten',
  'Haz clic en cualquier celda para editarla al momento. Las columnas de selección muestran opciones con color que puedes añadir sobre la marcha; las casillas se marcan con un clic. Pasa el ratón por una fila para borrarla.':
    'Klicken Sie auf eine beliebige Zelle, um sie sofort zu bearbeiten. Auswahlspalten zeigen farbige Optionen, die Sie spontan hinzufügen können; Kontrollkästchen werden mit einem Klick markiert. Fahren Sie mit der Maus über eine Zeile, um sie zu löschen.',
  'Columnas a tu medida': 'Spalten nach Maß',
  'Pulsa la cabecera de una columna para renombrarla, cambiar su tipo o gestionar sus opciones, y usa el botón + del final de la cabecera para añadir nuevas columnas. Con «Nueva fila» añades registros.':
    'Klicken Sie auf die Kopfzeile einer Spalte, um sie umzubenennen, ihren Typ zu ändern oder ihre Optionen zu verwalten, und nutzen Sie die Schaltfläche + am Ende der Kopfzeile, um neue Spalten hinzuzufügen. Mit „Neue Zeile“ fügen Sie Datensätze hinzu.',
  'Análisis (próximamente)': 'Analyse (demnächst)',
  'Aquí podrás elegir una base de datos y obtener estadísticas automáticas más un informe con IA, con gráficos y el cálculo a la vista para que sea reproducible. Llega en una próxima fase.':
    'Hier können Sie eine Datenbank auswählen und automatische Statistiken sowie einen KI-Bericht erhalten, mit Diagrammen und offen einsehbarer Berechnung, damit alles nachvollziehbar bleibt. Kommt in einer späteren Phase.',
  'Chat de datos (próximamente)': 'Daten-Chat (demnächst)',
  'Un chat adaptado para conversar con una o varias de tus bases de datos, capaz de generar gráficos y consultas reproducibles. También llega en una próxima fase.':
    'Ein Chat, mit dem Sie sich mit einer oder mehreren Ihrer Datenbanken unterhalten können und der Diagramme und nachvollziehbare Abfragen erstellen kann. Kommt ebenfalls in einer späteren Phase.',
  'Listo para tus datos': 'Bereit für Ihre Daten',
  'Esto es una demostración con datos de ejemplo. Cuando quieras empezar con los tuyos, crea una base de datos desde la barra lateral y añade tus columnas. Pronto podrás además importar CSV y subir archivos en masa.':
    'Dies ist eine Demo mit Beispieldaten. Wenn Sie mit Ihren eigenen beginnen möchten, erstellen Sie über die Seitenleiste eine Datenbank und fügen Sie Ihre Spalten hinzu. Bald können Sie außerdem CSV importieren und Dateien in großen Mengen hochladen.',
