  'No, ahora no': 'Nein, jetzt nicht',
  'Nodus puede extraer conceptos, relaciones y citas textuales para crear el mapa de Ideas y el grafo de estudio.': 'Nodus kann Konzepte, Beziehungen und wörtliche Zitate extrahieren, um die Ideenkarte und den Lern-Graphen zu erstellen.',
  'El análisis se realizará en este dispositivo con el modelo seleccionado; el archivo no saldrá del equipo.': 'Die Analyse wird mit dem ausgewählten Modell auf diesem Gerät durchgeführt; die Datei verlässt den Computer nicht.',
  'Se enviarán al proveedor indicado el título y el texto extraído necesario. El archivo original permanecerá en tu dispositivo.': 'Der Titel und der erforderliche extrahierte Text werden an den angegebenen Anbieter gesendet. Die Originaldatei bleibt auf Ihrem Gerät.',
  'caracteres extraídos': 'extrahierte Zeichen',
  'No volver a preguntar': 'Nicht erneut fragen',
  'Procesamiento de materiales nuevos con IA': 'KI-Verarbeitung neuer Materialien',
  'Controla si Nodus crea automáticamente conceptos, citas y relaciones para el mapa de Ideas y el grafo de estudio.': 'Legt fest, ob Nodus automatisch Konzepte, Zitate und Beziehungen für die Ideenkarte und den Lern-Graphen erstellt.',
  'Preguntar cada vez': 'Jedes Mal fragen',
  'Procesar automáticamente': 'Automatisch verarbeiten',
