  'Analíticas de estudio desactivadas': 'Studienanalysen deaktiviert',
  'Puedes activarlas en Ajustes → Modelos IA. Los repasos siguen funcionando localmente.':
    'Sie können sie unter Einstellungen → KI-Modelle aktivieren. Wiederholungen funktionieren weiterhin lokal.',
  'Modelos de IA': 'KI-Modelle',
  'Un modelo general atiende conversación, análisis, resúmenes y las demás tareas de texto. Las capacidades especializadas se configuran debajo.':
    'Ein allgemeines Modell übernimmt Unterhaltung, Analyse, Zusammenfassungen und weitere Textaufgaben. Spezialisierte Funktionen werden weiter unten konfiguriert.',
  'El modelo general sigue siendo la base. Cada selector vacío hereda de él; los modelos de las herramientas se guardan solo en el vault actual.':
    'Das allgemeine Modell bleibt die Basis. Jeder leere Selektor übernimmt es; die Modelle der Werkzeuge werden nur im aktuellen Arbeitsbereich gespeichert.',
  'Cada tarea utiliza el modelo concreto seleccionado. Los modelos de las herramientas se guardan solo en el vault actual.':
    'Jede Aufgabe verwendet das konkret ausgewählte Modell. Die Modelle der Werkzeuge werden nur im aktuellen Arbeitsbereich gespeichert.',
  'Modelo general de texto': 'Allgemeines Textmodell',
  'Conversación, análisis, resúmenes y fallback de cualquier tarea sin modelo propio.':
    'Unterhaltung, Analyse, Zusammenfassungen und Fallback für jede Aufgabe ohne eigenes Modell.',
  'Conversación, análisis, resúmenes y demás tareas de texto.': 'Unterhaltung, Analyse, Zusammenfassungen und weitere Textaufgaben.',
  'Este modelo consume la cuota de tu suscripción, no crédito de API. Un análisis completo del corpus puede agotar el límite semanal o mensual de tu plan.':
    'Dieses Modell verbraucht das Kontingent Ihres Abonnements, kein API-Guthaben. Eine vollständige Korpusanalyse kann das Wochen- oder Monatslimit Ihres Tarifs aufbrauchen.',
  'Este modelo local es de visión y no extrae ideas de forma fiable (tiende a divagar y no cerrar el JSON). Para extracción, elige Gemma 4 E2B u otro modelo mayor.':
    'Dieses lokale Modell ist auf Vision ausgelegt und extrahiert Ideen nicht zuverlässig (es neigt dazu, abzuschweifen und das JSON nicht zu schließen). Wählen Sie zur Extraktion Gemma 4 E2B oder ein größeres Modell.',
  "Estos pesos son los mismos que Nodus descarta entre sus modelos integrados: al extraer ideas divagan y no cierran el JSON. Puedes usarlos igualmente, pero para extracción conviene un modelo mayor.": "Das sind dieselben Gewichte, die Nodus unter seinen integrierten Modellen ausschließt: Beim Extrahieren von Ideen schweifen sie ab und schließen das JSON nie. Sie können sie trotzdem verwenden, für die Extraktion eignet sich jedoch ein größeres Modell besser.",
  "El paso falló sin dejar un motivo. Reintenta; si vuelve a fallar, revisa el modelo en Ajustes → Modelos de IA.": "Der Schritt ist fehlgeschlagen, ohne einen Grund festzuhalten. Versuchen Sie es erneut; scheitert er wieder, prüfen Sie das Modell unter Einstellungen → KI-Modelle.",
  "Todavía no hay ningún modelo entre los que elegir. Pulsa «Cargar modelos» para ver los de tus proveedores, o marca los que quieras como favoritos en Ajustes → Proveedores de IA y modelos.": "Hier steht noch kein Modell zur Auswahl. Klicken Sie auf „Modelle laden“, um die Modelle Ihrer Anbieter zu sehen, oder markieren Sie die gewünschten als Favoriten unter Einstellungen → KI-Anbieter und Modelle.",
  "Sin respuesta de {list}. Revisa su clave o que el servidor local esté abierto.": "Keine Antwort von {list}. Prüfen Sie den Schlüssel oder ob der lokale Server läuft.",
  'solo visión':
    'nur Vision',
  'Este modelo no puede usarse para extracción de ideas.':
    'Dieses Modell kann nicht für die Ideenextraktion verwendet werden.',
  'Uso mi plan gratuito de este proveedor':
    'Ich nutze den kostenlosen Tarif dieses Anbieters',
  'Ajusta las peticiones a los límites del nivel gratuito (recorta la longitud de salida y espera si se alcanza el límite por minuto) para que el análisis no falle. Déjalo desmarcado si pagas por uso.':
    'Passt die Anfragen an die Limits des kostenlosen Tarifs an (kürzt die Ausgabelänge und wartet, wenn das Minutenlimit erreicht ist), damit die Analyse nicht fehlschlägt. Deaktiviert lassen, wenn Sie pro Nutzung zahlen.',
