  'Mejora de texto': 'Textverbesserung',
  'Detalles y fuente': 'Details und Quelle',
  'Verificar ideas extraídas': 'Extrahierte Ideen überprüfen',
  'Cada idea aparece con su tipo (afirmación, hallazgo, constructo, método o marco), la obra de la que procede y la cita textual que la sostiene. Abre el detalle para comprobar si la lectura automática coincide con la tuya.':
    'Jede Idee wird mit ihrem Typ (Aussage, Befund, Konstrukt, Methode oder Rahmen), dem Werk, aus dem sie stammt, und dem wörtlichen Zitat angezeigt, das sie stützt. Öffnen Sie die Detailansicht, um zu prüfen, ob die automatische Lesart mit Ihrer eigenen übereinstimmt.',
  'Busca por palabras clave a través de ideas, obras, huecos, temas, autores y notas. Los resultados te llevan directamente al detalle correspondiente en cada vista.':
    'Suchen Sie mit Stichwörtern in Ideen, Werken, Lücken, Themen, Autoren und Notizen. Die Ergebnisse führen Sie direkt zur entsprechenden Detailansicht in jeder Ansicht.',
  'Tu espacio de notas': 'Ihr Notizbereich',
  'Crea carpetas y notas en Markdown. Captura respuestas del asistente, borradores del taller de escritura, síntesis de debates e ideas individuales. Las citas internas (nodus://) permanecen clicables.':
    'Erstellen Sie Ordner und Notizen in Markdown. Erfassen Sie Antworten des Assistenten, Entwürfe aus der Schreibwerkstatt, Debattenzusammenfassungen und einzelne Ideen. Interne Zitate (nodus://) bleiben anklickbar.',
  'Debates: la estructura de una contradicción': 'Debatten: die Struktur eines Widerspruchs',
  'Cada relación de contradicción o refutación se despliega como un debate de dos bandos con sus autores, evidencias y cronología. Pides una síntesis al modelo para entender la tensión y decides cómo tu trabajo puede resolverla o aprovecharla.':
    'Jede Widerspruchs- oder Widerlegungsbeziehung entfaltet sich als Debatte mit zwei Seiten, ihren Autoren, Belegen und einer Chronologie. Sie bitten das Modell um eine Synthese, um die Spannung zu verstehen, und entscheiden, wie Ihre Arbeit sie auflösen oder nutzen kann.',
  'Mapa de cobertura: tu pregunta descompuesta': 'Abdeckungskarte: Ihre Frage aufgeschlüsselt',
  'Escribe tu pregunta de investigación y Nodus la desglosa en subpreguntas. Después mapea cuáles cubre tu corpus, cuáles parcialmente y cuáles quedan sin literatura. Es la herramienta para convertir una intuición vaga en un plan de búsqueda estructurado.':
    'Geben Sie Ihre Forschungsfrage ein, und Nodus gliedert sie in Unterfragen. Anschließend zeigt es, welche Ihr Korpus abdeckt, welche nur teilweise und welche ohne Literatur bleiben. Damit wird aus einer vagen Idee ein strukturierter Rechercheplan.',
  'Notas: tu cuaderno de investigación': 'Notizen: Ihr Forschungsnotizbuch',
  'A lo largo del proceso habrás generado hallazgos en el asistente, borradores en el taller y síntesis de debates. Las Notas te permiten organizar todo ello en carpetas jerárquicas — piensa en capítulos y secciones — con un editor Markdown que conserva las citas clicables. Las ideas manuales que crees aquí se integran directamente en el grafo.':
    'Im Laufe des Prozesses entstehen Befunde im Assistenten, Entwürfe in der Werkstatt und Zusammenfassungen von Debatten. Mit Notizen organisieren Sie alles in hierarchischen Ordnern — denken Sie an Kapitel und Abschnitte — mit einem Markdown-Editor, der anklickbare Zitate erhält. Manuelle Ideen, die Sie hier erstellen, fließen direkt in den Graphen ein.',
  'Inicio resume el estado de tu corpus, los análisis pendientes y el siguiente paso recomendado. La investigación es iterativa: escaneas más obras, vuelven a aparecer ideas y huecos, refinas la ruta y el borrador. Vuelve aquí entre vueltas. Puedes relanzar este recorrido desde Ajustes → Ayuda.':
    'Start fasst den Status Ihres Korpus, die ausstehenden Analysen und den empfohlenen nächsten Schritt zusammen. Forschung ist iterativ: Sie scannen weitere Werke, es tauchen neue Ideen und Lücken auf, Sie verfeinern den Weg und den Entwurf. Kehren Sie zwischen den Runden hierher zurück. Sie können diese Tour jederzeit über Einstellungen → Hilfe neu starten.',
  'RECUPERACIÓN ACTIVADA': 'WIEDERHERSTELLUNG AKTIVIERT',
  'Tus datos ya están protegidos': 'Ihre Daten sind jetzt geschützt',
  'Tus datos se han recuperado': 'Ihre Daten wurden wiederhergestellt',
