  'Clave de recuperación independiente': 'Unabhängiger Wiederherstellungsschlüssel',
  'Permite recuperar tus copias aunque olvides la contraseña.': 'Ermöglicht die Wiederherstellung Ihrer Sicherungen, auch wenn Sie das Passwort vergessen.',
  'Copiar clave': 'Schlüssel kopieren',
  'Guarda el kit fuera de este dispositivo. Podrás restaurar con la contraseña o con la clave de recuperación.':
    'Bewahren Sie das Kit außerhalb dieses Geräts auf. Sie können mit dem Passwort oder dem Wiederherstellungsschlüssel wiederherstellen.',
  'Continuar a Nodus': 'Weiter zu Nodus',
  'PROTECCIÓN DE DATOS': 'DATENSICHERUNG',
  'Hemos detectado una instalación anterior': 'Wir haben eine vorherige Installation erkannt',
  'Elige dónde proteger Nodus': 'Wählen Sie, wo Nodus geschützt werden soll',
  'Tus bóvedas actuales no se moverán ni se modificarán. Crearemos una primera copia cifrada y verificada antes de activar la recuperación.':
    'Ihre aktuellen Arbeitsbereiche werden weder verschoben noch verändert. Wir erstellen zuerst eine verschlüsselte und geprüfte Sicherung, bevor die Wiederherstellung aktiviert wird.',
  'Configura una carpeta segura antes de empezar. Tus bóvedas seguirán trabajando localmente y Nodus guardará aquí copias recuperables.':
    'Richten Sie vor dem Start einen sicheren Ordner ein. Ihre Arbeitsbereiche arbeiten weiterhin lokal, und Nodus speichert hier wiederherstellbare Sicherungen.',
  'La base de datos activa nunca se abre directamente desde Google Drive o Dropbox: así evitamos conflictos y corrupción.':
    'Die aktive Datenbank wird nie direkt aus Google Drive oder Dropbox geöffnet: So vermeiden wir Konflikte und Beschädigungen.',
  'Migrar y proteger este equipo': 'Diesen Computer migrieren und schützen',
  'Crear carpeta segura': 'Sicheren Ordner erstellen',
  'Recuperar otro equipo': 'Anderen Computer wiederherstellen',
