  "Los nombres de los grupos se sustituyen por identificadores antes de enviarlos, y se restauran al recibir la respuesta. No cubre transcripción de audio, análisis de imágenes ni embeddings.": "Schülernamen werden vor dem Senden durch Kennungen ersetzt und in der Antwort wiederhergestellt. Gilt nicht für Audiotranskription, Bildanalyse oder Embeddings.",
