  "Gracias por echar una mano con el diseño.": "Danke, dass du beim Entwurf hilfst.",
  "Redactar y mantener la programación didáctica del curso, conectada con los materiales, las unidades y los criterios que ya usas para calificar.": "Den Jahresplan schreiben und pflegen, verknüpft mit Materialien, Einheiten und den Kriterien, die du schon zum Benoten nutzt.",
  "La pieza intermedia entre la programación anual y el día a día: temporalización, actividades, recursos y criterios que alimentan el cuaderno de notas.": "Die Ebene zwischen Jahresplan und Alltag: Zeitplanung, Aktivitäten, Material und die Kriterien, die ins Notenbuch fließen.",
  "Diseñar situaciones de aprendizaje completas: contexto, reto, producto final, secuencia de actividades y competencias implicadas.": "Vollständige Lernsituationen entwerfen: Kontext, Herausforderung, Endprodukt, Aktivitätsfolge und beteiligte Kompetenzen.",
  "Gestionar adaptaciones y medidas de atención a la diversidad por alumno o por grupo, con su seguimiento y su reflejo en la evaluación.": "Anpassungen und Fördermaßnahmen pro Schüler oder Gruppe verwalten, samt Verlauf und Auswirkung auf die Bewertung.",
  "Un cuaderno del docente: observaciones de clase, incidencias y seguimiento, con la opción de colgar cada nota de un curso, grupo o alumno.": "Ein Lehrertagebuch: Beobachtungen, Vorfälle und Verlauf, mit der Option, jede Notiz einem Kurs, einer Gruppe oder einem Schüler zuzuordnen.",
