  "El PowerPoint tiene {pptx} diapositivas y el PDF tiene {pdf}. Deben coincidir para importar las notas.": "Die PowerPoint-Datei hat {pptx} Folien und das PDF hat {pdf}. Sie müssen übereinstimmen, um die Notizen zu importieren.",
