  'Zotero está abierto y se cerrará para instalar el plugin; se reabrirá al terminar. ¿Continuar?': 'Zotero ist geöffnet und wird zum Installieren des Plugins geschlossen; es wird danach wieder geöffnet. Fortfahren?',
