  'Personalidad': 'Persönlichkeit',
  'Cómo es y cómo habla.': 'Wie sie ist und wie sie spricht.',
  'Carácter, motivaciones, miedos, forma de hablar…': 'Charakter, Motive, Ängste, Sprechweise…',
  'Trasfondo': 'Vorgeschichte',
  'De dónde viene y qué le ha pasado.': 'Woher sie kommt und was ihr widerfahren ist.',
  'Origen, historia previa, cómo llega al punto en que empieza el relato…': 'Herkunft, Vorgeschichte, wie sie an den Punkt gelangt, an dem die Erzählung beginnt…',
  'Semilla visual': 'Visueller Kern',
  'Un texto corto y estable que se añade a TODAS las imágenes que generes de este personaje. Es lo que consigue que se parezca a sí mismo de una imagen a otra, así que conviene cambiarlo lo menos posible.': 'Ein kurzer, stabiler Text, der JEDEM Bild dieser Figur beigefügt wird. Er sorgt dafür, dass sie sich von Bild zu Bild gleicht — ändere ihn also möglichst selten.',
  'p. ej. «semielfo de rasgos afilados, pelo negro recogido, ojos ámbar»': 'z. B. „Halbelf mit scharfen Zügen, schwarzem zurückgebundenem Haar, bernsteinfarbenen Augen“',
  'Usar la apariencia como semilla': 'Aussehen als Kern verwenden',
  'Redacta una biografía narrativa a partir de la ficha: su descripción, sus eventos y sus vínculos.': 'Schreibe eine erzählende Biografie aus dem Steckbrief: Beschreibung, Ereignisse und Bindungen.',
  'Rellena al menos la descripción, un evento o un vínculo antes de generar la biografía.': 'Fülle mindestens die Beschreibung, ein Ereignis oder eine Bindung aus, bevor du die Biografie erzeugst.',
