  'p. ej. 1204 (admite negativos)': 'z. B. 1204 (negative Werte erlaubt)',
  'La fecha se escribe como quieras; el año del mundo es lo que ordena la lista.': 'Schreibe das Datum wie du willst; die Reihenfolge der Liste ergibt sich aus dem Weltjahr.',
  '{n} sin año del mundo: aparecen al final hasta que les pongas uno.': '{n} ohne Weltjahr: Sie bleiben am Ende, bis du eines angibst.',
  'Nacimiento (texto libre)': 'Geburt (Freitext)',
