  'Año del mundo · nacimiento': 'Weltjahr · Geburt',
  'Año del mundo · muerte': 'Weltjahr · Tod',
  'La fecha se muestra tal como la escribas. El año del mundo es un entero y sirve solo para ordenar.': 'Das Datum erscheint genau so, wie du es schreibst. Das Weltjahr ist eine ganze Zahl und dient nur der Sortierung.',
  'Subir imagen': 'Bild hochladen',
  'Arrastra para encuadrar': 'Zum Ausrichten ziehen',
  'Arrastra la imagen para encuadrarla y usa el zoom.': 'Zieh das Bild, um es auszurichten, und nutze den Zoom.',
  'Retrato con IA': 'KI-Porträt',
  'Se usa la apariencia y la semilla visual de la ficha, así que el personaje mantiene el mismo aspecto entre imágenes.': 'Es werden Aussehen und visueller Kern des Steckbriefs verwendet, damit die Figur über Bilder hinweg gleich aussieht.',
  'Escribe primero la apariencia del personaje en la sección Descripción.': 'Trage zuerst das Aussehen der Figur im Abschnitt Beschreibung ein.',
  'Solo para esta imagen: pose, gesto, ropa, luz… (opcional)': 'Nur für dieses Bild: Haltung, Gestik, Kleidung, Licht… (optional)',
  'Tu mundo': 'Deine Welt',
  'Construye un mundo de ficción pieza a pieza. Empieza por los personajes: sus nombres y alias, los hechos de su vida, sus vínculos y su descripción, con retratos y biografías que puedes generar cuando te sirvan.': 'Baue eine erfundene Welt Stück für Stück. Beginne mit den Figuren: ihre Namen und Aliasse, die Ereignisse ihres Lebens, ihre Bindungen und ihre Beschreibung — mit Porträts und Biografien, die du erzeugen kannst, wann sie dir nützen.',
  'Personajes recientes': 'Zuletzt bearbeitete Figuren',
  'Ver todos': 'Alle ansehen',
  'En construcción': 'In Arbeit',
  'Las demás secciones del menú ({sections}) aparecen atenuadas porque todavía no están construidas. Se irán activando una a una.': 'Die übrigen Bereiche im Menü ({sections}) sind abgeblendet, weil sie noch nicht gebaut sind. Sie werden einer nach dem anderen freigeschaltet.',
  'enciclopedia, lugares, facciones, culturas, cronología, mapa, relaciones, escenas y manuscritos': 'Enzyklopädie, Orte, Fraktionen, Kulturen, Chronologie, Karte, Beziehungen, Szenen und Manuskripte',
