  '«¿A quién no soportas y por qué?»': '„Wen erträgst du nicht, und warum?“',
  '«¿Qué harías si te quitaran lo que más quieres?»': '„Was tätest du, wenn man dir das Liebste nähme?“',
  'Exportar la ficha a Markdown': 'Steckbrief als Markdown exportieren',
  'Ficha guardada en {path}': 'Steckbrief gespeichert unter {path}',
  '(sin los nombres secretos ni tus notas privadas)': '(ohne die geheimen Namen und deine privaten Notizen)',
  'Plantilla': 'Vorlage',
  'Solo el nombre. Rellena la ficha a tu manera.': 'Nur der Name. Fülle den Steckbrief nach deiner Art.',
  'Héroe a su pesar': 'Held wider Willen',
  'Alguien a quien la trama saca de su vida sin pedirle permiso. Empieza por qué quería en realidad y qué le impide moverse.': 'Jemand, den die Handlung ungefragt aus dem Leben reißt. Beginne damit, was sie eigentlich wollte und was sie festhält.',
  'Tirano con razones': 'Tyrann mit Gründen',
  'Un antagonista que cree estar salvando algo. Lo importante es la mentira que se cree y de dónde salió.': 'Ein Antagonist, der glaubt, etwas zu retten. Wichtig ist die Lüge, die er glaubt, und woher sie kommt.',
  'Mentor con secreto': 'Mentor mit Geheimnis',
  'Quien enseña y calla lo que más importa. Define qué protege ocultándolo.': 'Wer lehrt und das Wichtigste verschweigt. Lege fest, was er damit schützt.',
  'Embaucador': 'Schwindler',
  'Quien sobrevive hablando y cambia de bando a tiempo. Su voz es media ficha.': 'Wer durchs Reden überlebt und rechtzeitig die Seiten wechselt. Die Stimme ist die halbe Figur.',
  'Testigo': 'Zeuge',
  'Un personaje menor que ve lo que nadie más ve. Con poco basta: qué vio y por qué calla.': 'Eine Nebenfigur, die sieht, was niemand sonst sieht. Wenig genügt: was sie sah und warum sie schweigt.',
