  'Opcional. Sin calendario, el año ordena la cronología igual que hasta ahora; con él, además ordena dentro de cada año y puedes elegir la fecha en vez de escribirla.': 'Optional. Ohne Kalender ordnet das Jahr die Chronologie wie bisher; mit Kalender ordnet es zusätzlich innerhalb des Jahres, und du wählst das Datum statt es zu tippen.',
