  'Lo que dirías de esto en una frase.': 'Was du in einem Satz darüber sagen würdest.',
  'Lo que se ve: emblemas, colores, vestimenta, arquitectura.': 'Was sichtbar ist: Wappen, Farben, Kleidung, Architektur.',
  'Símbolos, atuendo, cómo se reconoce a los suyos…': 'Symbole, Kleidung, woran man die Ihren erkennt…',
  'Lo que se añade a todas las imágenes para que se parezcan entre sí.': 'Wird jedem Bild beigefügt, damit sie einander gleichen.',
  'p. ej. «heráldica de cuervo negro sobre campo gris, plata bruñida»': 'z. B. „Wappen mit schwarzem Raben auf grauem Feld, poliertes Silber“',
  'p. ej. «los espías de la corte, que ya no responden ante nadie»': 'z. B. „die Spione des Hofes, die niemandem mehr Rechenschaft schulden“',
