  'Lo que ocurre en la escena, en tus palabras.': 'Was in der Szene geschieht, in deinen Worten.',
  'Quién quiere qué, quién se lo impide y cómo acaba…': 'Wer was will, wer es verhindert und wie es endet…',
  'Quién aparece': 'Wer auftritt',
  'Añadir personaje a la escena': 'Figur zur Szene hinzufügen',
  'Crea antes algún personaje.': 'Lege zuerst eine Figur an.',
  '¿Eliminar esta escena? Los personajes que aparecen en ella NO se borran.': 'Diese Szene löschen? Die darin auftretenden Figuren werden NICHT gelöscht.',
  'El año es cuándo ocurre en el mundo; el orden es dónde va en el relato. Un prólogo ambientado siglos antes va primero en el relato y último en la cronología.': 'Das Jahr ist, wann es in der Welt geschieht; die Reihenfolge, wo es in der Erzählung steht. Ein Prolog, der Jahrhunderte früher spielt, kommt in der Erzählung zuerst und in der Chronologie zuletzt.',
  'Apariciones': 'Auftritte',
  'En orden del relato, no de la cronología.': 'In der Reihenfolge der Erzählung, nicht der Chronologie.',
  'Secretos': 'Geheimnisse',
  'Añadir secreto': 'Geheimnis hinzufügen',
  'Qué esconde…': 'Was sie verbirgt…',
  'No esconde nada por ahora.': 'Verbirgt noch nichts.',
  'Revelado': 'Enthüllt',
  'Además sabe': 'Weiß außerdem',
  'Diseña unidades para el docente o apuntes para entregar al alumnado, siempre desde tus fuentes.': 'Entwirf Unterrichtseinheiten für Lehrkräfte oder ausgabefertige Lernunterlagen, stets auf Grundlage deiner Quellen.',
  'Elige si necesitas una planificación para impartir la lección o apuntes listos para entregar.': 'Wähle zwischen einem Plan für die Unterrichtsstunde und ausgabefertigen Lernunterlagen.',
  'Elige si necesitas apuntes para aprender o una planificación para enseñar el tema.': 'Wähle zwischen Lernunterlagen zum Lernen und einem Plan zum Unterrichten des Themas.',
  'Escribe el tema o la lección que quieres preparar. El informe diseñará objetivos, secuencia, actividades y evaluación usando tus materiales.': 'Gib das Thema oder die Stunde ein, die du vorbereiten möchtest. Der Bericht entwirft Lernziele, Ablauf, Aktivitäten und Bewertung anhand deiner Materialien.',
  'Escribe el tema de los apuntes. El informe lo explicará paso a paso con ejemplos y autoevaluación usando tus materiales.': 'Gib das Thema der Lernunterlagen ein. Der Bericht erklärt es anhand deiner Materialien Schritt für Schritt mit Beispielen und Selbstkontrolle.',
  'Público objetivo y producto': 'Zielgruppe und Ergebnis',
  'Docente · planificación de la lección': 'Lehrkraft · Unterrichtsplanung',
  'Alumnado · apuntes para entregar': 'Lernende · ausgabefertige Unterlagen',
  'Generará objetivos, secuencia, actividades, comprobaciones de comprensión y evaluación para el docente.': 'Erstellt Lernziele, Ablauf, Aktivitäten, Verständnisprüfungen und Bewertung für die Lehrkraft.',
  'Generará explicaciones, definiciones, ejemplos, síntesis y autoevaluación dirigidos al alumnado.': 'Erstellt Erklärungen, Definitionen, Beispiele, Zusammenfassungen und Selbstkontrollen für die Lernenden.',
  'En «Crear», Unidades didácticas ya permite generar una planificación para el docente o apuntes para el alumnado a partir de tus materiales. Las demás secciones punteadas siguen abiertas a tus sugerencias. Puedes repetir este tutorial desde Ajustes.': 'Unter „Erstellen“ können Unterrichtseinheiten jetzt aus deinen Materialien entweder eine Planung für Lehrkräfte oder Lernunterlagen erzeugen. Die übrigen gepunkteten Bereiche sind weiterhin offen für deine Vorschläge. Dieses Tutorial lässt sich in den Einstellungen erneut starten.',
  'Artefacto': 'Artefakt',
