  'Crear la entrada «{name}»': 'Eintrag „{name}“ anlegen',
  'Los artículos son para lo que no es un personaje, un lugar ni una facción: la magia, una religión, una lengua, una criatura, un objeto. Todo lo demás ya está en la enciclopedia por sí solo.': 'Artikel sind für alles, was weder Figur noch Ort noch Fraktion ist: Magie, eine Religion, eine Sprache, ein Wesen, ein Gegenstand. Alles andere steht schon von selbst in der Enzyklopädie.',
  'Nuevo artículo': 'Neuer Artikel',
  'Todavía nadie ha definido esto. Al crearlo, todas las menciones que lo esperaban quedarán enlazadas.': 'Das hat noch niemand definiert. Beim Anlegen werden alle wartenden Erwähnungen verknüpft.',
