  'Esta ficha aún no tiene texto. Se escribe en su propia sección.': 'Dieses Blatt hat noch keinen Text. Er wird im eigenen Bereich geschrieben.',
  'Ficha completa': 'Vollständiges Blatt',
  'Las menciones que la enlazaban no se borran: quedarán marcadas como pendientes.': 'Die Erwähnungen, die darauf verwiesen, werden nicht gelöscht: sie werden als offen markiert.',
