  'Buscar «{query}» en el texto completo': '„{query}“ im Volltext suchen',
  'Con texto': 'Mit Text',
  'Este mundo todavía está vacío.': 'Diese Welt ist noch leer.',
  'Ninguna entrada coincide con el filtro.': 'Kein Eintrag passt zum Filter.',
  'Sin desarrollar': 'Unausgeführt',
  'Tipo de entrada': 'Eintragsart',
  '{count} en el texto completo': '{count} im Volltext',
  '«{query}» no aparece en ningún texto del mundo.': '„{query}“ kommt in keinem Text dieser Welt vor.',
  'reglas del mundo, conflictos, arcos narrativos, consistencia, preguntas abiertas, tramas y manuscritos': 'Weltregeln, Konflikte, Erzählbögen, Konsistenz, offene Fragen, Handlungsstränge und Manuskripte',
  'En la enciclopedia': 'In der Enzyklopädie',
  '{count} sin desarrollar': '{count} unausgeführt',
  'Construye un mundo de ficción pieza a pieza: personajes, lugares, facciones, culturas, escenas y mapas. La enciclopedia los reúne todos en un solo índice y te deja escribir el resto del mundo —la magia, una religión, una lengua— enlazándolo con [[dobles corchetes]].': 'Baue eine erfundene Welt Stück für Stück: Figuren, Orte, Fraktionen, Kulturen, Szenen und Karten. Die Enzyklopädie führt alles in einem Index zusammen und lässt dich den Rest der Welt schreiben — Magie, eine Religion, eine Sprache — verlinkt mit [[doppelten Klammern]].',
  'Analizar el mundo': 'Die Welt analysieren',
  'Aparecen a menudo y no están definidos': 'Sie kommen oft vor und sind nicht definiert',
  'Esto es una sospecha, no un hecho: son nombres que se repiten en tus textos.': 'Das ist eine Vermutung, keine Tatsache: Namen, die in deinen Texten wiederkehren.',
  'Lo escribiste tú entre dobles corchetes, así que ya existen en tu mundo.': 'Du hast sie selbst in doppelten Klammern geschrieben, also existieren sie schon in deiner Welt.',
  'Lo que falta por definir': 'Noch zu definieren',
  'Los enlazaste y no existen': 'Du hast sie verlinkt, und es gibt sie nicht',
