  "Borrar las cookies cerrará tu sesión en los sitios donde la tengas iniciada.": "Das Löschen von Cookies meldet Sie von den Websites ab, bei denen Sie angemeldet sind.",
  "También se cerrarán todas las pestañas abiertas del navegador.": "Alle geöffneten Browser-Tabs werden ebenfalls geschlossen.",
  "Chromium borra las cookies por dominio registrable: al borrar las de un subdominio se borran también las del dominio principal y sus demás subdominios.": "Chromium löscht Cookies nach registrierbarer Domain: Cookies einer Subdomain zu löschen löscht auch die der Hauptdomain und ihrer übrigen Subdomains.",
  "Nodus puede medir la caché y el tamaño total del perfil. Chromium no informa del tamaño de cada categoría de almacenamiento por separado, así que las demás se muestran por número de sitios afectados.": "Nodus kann den Cache und die Gesamtgröße des Profils messen. Chromium meldet die Größe der einzelnen Speicherkategorien nicht separat, daher werden die übrigen nach Anzahl betroffener Websites angezeigt.",
  "Nodus Browser conserva cookies y almacenamiento de sitio para que sigas con la sesión iniciada donde corresponda. Nodus no guarda usuarios ni contraseñas, y no incluye gestor de contraseñas.": "Nodus Browser behält Cookies und Website-Speicher, damit Sie angemeldet bleiben, wo es sinnvoll ist. Nodus speichert weder Benutzernamen noch Passwörter und enthält keinen Passwortmanager.",
